contract WeakPRNGTest is Test {
    RandomNumberGenerator rng;

    function setUp() public {
        rng = new RandomNumberGenerator();
    }

    function testWeakPRNG() public {
        // Take snapshot to preserve original contract state
        uint256 snapshotId = vm.snapshot();

        // First playGame call
        rng.playGame(1);
        uint256 firstResult = rng.winningNumber();

        // Revert state while keeping same block context
        vm.revertTo(snapshotId);

        // Second playGame call with same inputs and blockchain context
        rng.playGame(1);
        uint256 secondResult = rng.winningNumber();

        // Validate identical results demonstrate weak PRNG
        assertEq(firstResult, secondResult, "Weak PRNG produces identical results in same blockchain conditions");
    }
}
